# Search and export

Add `GET /search?q=<text>` to the existing server. Normalize searchable text with Unicode NFKC and case-fold it, then tokenize maximal Unicode alphanumeric runs. Normalize query terms the same way. Every query term must occur in at least one of the ticket subject, ticket body, or any comment body.

For each matching ticket, count occurrences of all query terms in each field group. Its score is `3 * subject_hits + 2 * body_hits + comment_hits`. Return `{"tickets": [...]}` with each full ticket record plus integer `score`, ordered by descending score, then descending normalized `updated_at`, then ascending numeric ticket ID. The same token repeated in the query is counted once.

Add:

```bash
cd service
python -m helpdesk export ../workspace/helpdesk.db --status open --output ../output/tickets.csv
```

Export matching tickets in ascending numeric ticket ID with exact header:

```text
ticket_id,subject,status,priority,assignee_email,requester_email,created_at,updated_at,sla_due_at
```

The status filter is required. Use an empty field for null values and normal CSV quoting with LF record endings.
import unicodedata
from .models import ticket as serialize


def search(conn, query):
    if not isinstance(query, str) or not query.strip():
        return []
    needle = unicodedata.normalize("NFKC", query).casefold()
    comments = {}
    for row in conn.execute("SELECT ticket_id, body FROM comments ORDER BY id"):
        comments.setdefault(row["ticket_id"], []).append(row["body"])
    found = []
    for row in conn.execute("SELECT * FROM tickets ORDER BY id"):
        haystack = "\n".join((row["subject"], row["body"], row["requester_email"], *comments.get(row["id"], [])))
        if needle in unicodedata.normalize("NFKC", haystack).casefold():
            found.append(serialize(row))
    return found
from .comments import listing as comments_for
from .jsonutil import dumps
from .models import ticket


def records(conn):
    result = []
    for row in conn.execute("SELECT * FROM tickets ORDER BY id"):
        item = ticket(row)
        item["comments"] = comments_for(conn, row["id"])
        result.append(item)
    return result


def write_jsonl(conn, path):
    with open(path, "wb") as stream:
        for item in records(conn):
            stream.write(dumps(item) + b"\n")
    return {"exported": len(records(conn)), "path": str(path)}
from urllib.parse import urlsplit, parse_qs
from . import comments, exporter, maintenance, search, tickets
from .errors import APIError
from .models import ticket as serialize_ticket


def route(conn, method, target, body):
    parsed = urlsplit(target)
    parts = [part for part in parsed.path.split("/") if part]
    query = parse_qs(parsed.query, keep_blank_values=True)
    if method == "GET" and parts == ["tickets"]:
        unknown = set(query) - {"status", "assignee", "q", "search"}
        if unknown: raise APIError(400, "unknown query parameters")
        if "q" in query or "search" in query:
            term = (query.get("q") or query.get("search"))[0]
            return 200, search.search(conn, term)
        status = query.get("status", [None])[0]
        marker = "assignee" in query
        assignee = None
        if marker:
            raw = query["assignee"][0]
            if not raw.isascii() or not raw.isdigit(): raise APIError(400, "assignee must be numeric")
            assignee = int(raw)
        return 200, tickets.listing(conn, status, marker, assignee)
    if method == "GET" and parts in (["search"], ["tickets", "search"]):
        return 200, search.search(conn, query.get("q", [""])[0])
    if method == "GET" and parts == ["export"]:
        return 200, exporter.records(conn)
    if method == "POST" and parts in (["maintenance", "stale"], ["maintenance"]):
        if not isinstance(body, dict) or "now" not in body: raise APIError(400, "missing fields: now")
        unknown = set(body) - {"now", "days"}
        if unknown: raise APIError(400, "unknown fields")
        days = body.get("days", 7)
        if isinstance(days, bool) or not isinstance(days, int): raise APIError(400, "days must be an integer")
        try: result = maintenance.close_stale(conn, body["now"], days)
        except ValueError as exc: raise APIError(400, str(exc)) from exc
        return 200, result
    if method == "POST" and parts == ["tickets"]:
        return 201, tickets.create(conn, body)
    if len(parts) >= 2 and parts[0] == "tickets":
        try:
            ticket_id = int(parts[1])
            if ticket_id < 1: raise ValueError
        except ValueError as exc:
            raise APIError(404, "ticket not found") from exc
        if method == "GET" and len(parts) == 2:
            row = tickets.get(conn, ticket_id)
            if row is None: raise APIError(404, "ticket not found")
            result = serialize_ticket(row)
            result["comments"] = comments.listing(conn, ticket_id)
            return 200, result
        if method == "PATCH" and len(parts) == 2:
            return 200, tickets.update(conn, ticket_id, body)
        if method == "POST" and len(parts) == 3 and parts[2] == "comments":
            return 201, comments.create(conn, ticket_id, body)
    raise APIError(404, "not found")
import argparse
import json
from . import agents, exporter, mail_import, maintenance, server, sla
from .db import connect


def _print(value):
    print(json.dumps(value, ensure_ascii=False, separators=(",", ":")), flush=True)


def main(argv=None):
    parser = argparse.ArgumentParser(prog="helpdesk")
    commands = parser.add_subparsers(dest="cmd", required=True)
    serve = commands.add_parser("serve")
    serve.add_argument("--db", required=True); serve.add_argument("--port", type=int, required=True)
    create = commands.add_parser("create-agent")
    create.add_argument("db"); create.add_argument("--email", required=True)
    imp = commands.add_parser("import-mbox")
    imp.add_argument("db"); imp.add_argument("mbox"); imp.add_argument("--priority", default="normal")
    mail = commands.add_parser("import-mail")
    mail.add_argument("db"); mail.add_argument("mbox")
    export = commands.add_parser("export")
    export.add_argument("db"); export.add_argument("output")
    escalations = commands.add_parser("escalations")
    escalations.add_argument("db"); escalations.add_argument("--as-of", required=True)
    escalations.add_argument("--output", required=True)
    for name in ("close-stale", "maintain"):
        stale = commands.add_parser(name)
        stale.add_argument("db"); stale.add_argument("--now", required=True); stale.add_argument("--days", type=int, default=7)
    args = parser.parse_args(argv)
    if args.cmd == "serve":
        server.serve(args.db, args.port)
        return
    conn = connect(args.db)
    try:
        if args.cmd == "create-agent": result = agents.create(conn, args.email)
        elif args.cmd == "import-mbox": result = mail_import.import_file(conn, args.mbox, args.priority)
        elif args.cmd == "import-mail": result = mail_import.import_file(conn, args.mbox)
        elif args.cmd == "export": result = exporter.write_jsonl(conn, args.output)
        elif args.cmd == "escalations":
            sla.write_escalations(conn, args.as_of, args.output)
            return
        else: result = maintenance.close_stale(conn, args.now, args.days)
        _print(result)
    finally:
        conn.close()
